INSERT INTO knowledge_base (question, answer, keywords, related_plans, category) VALUES
('久坐多久需要起身活动？', '建议每坐 45 到 60 分钟起身活动 2 到 3 分钟，做几个肩颈或腰背动作。WHO 与加拿大 24 小时运动指南都强调，打断长时间静坐比连续久坐更有利于健康。', '久坐,多久,起身,站起来,活动,休息', '[]', '久坐'),
('肩颈酸痛时可以运动吗？', '可以在疼痛允许的范围内保持活动，这通常比完全不动更有帮助。英国特许物理治疗学会指出，运动是缓解持续性颈部疼痛最有效的方法之一。若伴随手臂麻木、无力或头晕，请先就医。', '肩颈,脖子,颈椎,酸痛,僵硬,落枕', '[]', '肩颈'),
('腰痛还能继续运动吗？', '多数腰痛不需要卧床。英国 NHS 建议保持活动、尽量继续日常活动、避免长时间卧床。训练时以不引起明显疼痛加重为界；若出现双腿麻木无力、会阴部感觉丧失或大小便功能改变，请立即就医。', '腰痛,腰疼,腰背,腰,运动,卧床', '[]', '腰背'),
('每天练多久、练几次合适？', '每天 1 到 2 次、每次 3 到 10 分钟即可，关键是规律。成年人每周应累计至少 150 分钟中等强度活动，并每周至少 2 次力量训练。碎片时间累积同样有效。', '每天,多久,几次,频率,时长,时间', '[]', '运动量'),
('评估结果是高风险，还能运动吗？', '高风险期间不建议自行训练，请先前往骨科或康复科就诊，明确原因后再按医嘱恢复运动。本工具不提供诊断，也不能替代面诊。', '高风险,严重,就医,骨科,康复科,能不能练', '[]', '安全'),
('训练时疼痛加重怎么办？', '立即停止当前动作，休息并观察。若疼痛在几分钟内缓解，可减小幅度或缩短时间再试；若持续加重、出现麻木、无力或放射痛，请停止训练并及时就医。', '疼痛,加重,麻,无力,不舒服,停下', '[]', '安全'),
('在办公室工位能做什么动作？', '可以选择办公桌前场景的 3 分钟方案，包含颈部侧屈、肩部绕环、胸椎伸展、坐姿转体等不需要离开座位的动作。穿着正装时也能完成，不需要器械。', '办公室,工位,桌前,开会,上班,工位能', '[]', '场景'),
('运动后第二天肌肉酸胀正常吗？', '轻微酸胀通常属于正常的延迟性肌肉酸痛，1 到 3 天会自行缓解，可以继续低强度活动。若出现明显刺痛、关节肿痛或活动受限，应暂停并就医。', '酸胀,酸痛,第二天,延迟性,肌肉痛', '[]', '恢复'),
('久坐提醒怎么设置？', '在「提醒与追踪」页可设置提醒间隔与活跃时段，并开启浏览器通知。页面需要保持打开，提醒才会生效；关闭标签页后将无法推送。', '提醒,设置,通知,时段,间隔,闹钟', '[]', '功能'),
('什么情况必须去看医生？', '出现以下任一情况请立即就医：双腿疼痛、麻木或无力，会阴部感觉丧失，大小便功能改变，发热伴剧烈腰痛，或近期外伤后疼痛持续加重。', '医生,就医,医院,检查,急诊,必须看', '[]', '安全');